fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Get the number of rows and columns
    let rows = arr.len();
    let cols = arr[0].len();
    
    // Create a new matrix for the transposed result
    let mut transposed = vec![vec![0; rows]; cols];
    
    // Fill the transposed matrix
    for i in 0..rows {
        for j in 0..cols {
            transposed[j][i] = arr[i][j];
        }
    }
    
    transposed
}